// ── カラー定義 ─────────────────────────────────────────────────────────────
const C01 = "#ff7675";  // μ=0.01 赤
const C05 = "#74b9ff";  // μ=0.05 青

// ── ヘルパー ───────────────────────────────────────────────────────────────
const fmt = v =>
  v == null || !isFinite(v) ? "—"
  : Math.abs(v) >= 10  ? v.toFixed(2)
  : Math.abs(v) >= 0.1 ? v.toFixed(4)
  : v.toExponential(3);

const TooltipBox = ({ active, payload, label }) => {
  if (!active || !payload?.length) return null;
  const valid = payload.filter(p => p?.value != null && isFinite(p.value));
  if (!valid.length) return null;
  return (
    <div style={{ background:"#1a1a2e", border:"1px solid #444", borderRadius:8,
                   padding:"10px 14px", fontSize:11, color:"#eee", minWidth:230 }}>
      <div style={{ fontWeight:700, marginBottom:5, color:"#aef" }}>
        t = {Number(label).toFixed(4)} s
      </div>
      {valid.map(p => (
        <div key={p.dataKey} style={{ display:"flex", justifyContent:"space-between",
                                        gap:16, marginBottom:2 }}>
          <span style={{ color:p.color }}>{p.name}</span>
          <span style={{ fontFamily:"monospace" }}>{fmt(p.value)}</span>
        </div>
      ))}
    </div>
  );
};

const Panel = ({ title, sub, children }) => (
  <div style={{ background:"#161628", borderRadius:12,
                 padding:"14px 8px 8px", marginBottom:16,
                 border:"1px solid #2a2a4a" }}>
    <div style={{ fontSize:13, color:"#aef", fontWeight:600,
                   marginLeft:48, marginBottom:sub ? 1 : 4 }}>{title}</div>
    {sub && <div style={{ fontSize:11, color:"#888", marginLeft:48, marginBottom:4 }}>{sub}</div>}
    {children}
  </div>
);

const XAXIS = {
  dataKey:"t",
  tick:{ fill:"#888", fontSize:10 },
  tickFormatter: v => v.toFixed(3),
  label:{ value:"sim time (s)", position:"insideBottom", offset:-2,
           fill:"#888", fontSize:11 },
};
const GRID = { strokeDasharray:"3 3", stroke:"#2a2a4a" };
const LEG  = { wrapperStyle:{ fontSize:11, color:"#ccc", paddingTop:6 } };

// ── メインコンポーネント ───────────────────────────────────────────────────
export default function StillnessChart() {
  return (
    <div style={{ background:"#0f0f1a", minHeight:"100vh", color:"#eee",
                   fontFamily:"'Segoe UI',sans-serif", padding:"20px 16px" }}>

      {/* タイトル */}
      <h2 style={{ textAlign:"center", margin:"0 0 4px", fontSize:18,
                    color:"#7ecfff", letterSpacing:1 }}>
        静止判定データ 比較 — 人工粘性係数
      </h2>
      <div style={{ textAlign:"center", display:"flex", justifyContent:"center",
                     gap:28, fontSize:13, marginBottom:20 }}>
        <span style={{ color:C01, fontWeight:700 }}>
          <span style={{ fontSize:16 }}>━</span> μ = 0.01
        </span>
        <span style={{ color:C05, fontWeight:700 }}>
          <span style={{ fontSize:16 }}>╌</span> μ = 0.05
        </span>
      </div>

      {/* ── ① 速度（RMS・最大） ─────────────────────────────────────── */}
      <Panel
        title="① 速度 — RMS速度 & 最大速度"
        sub="実線 = RMS速度　破線 = 最大速度　単位 (m/s)">
        <ResponsiveContainer width="100%" height={300}>
          <LineChart data={DATA} margin={{ top:4, right:24, bottom:14, left:10 }}>
            <CartesianGrid {...GRID} />
            <XAxis {...XAXIS} />
            <YAxis
              tick={{ fill:"#888", fontSize:10 }}
              label={{ value:"速度 (m/s)", angle:-90, position:"insideLeft",
                        fill:"#888", fontSize:11 }} />
            <Tooltip content={<TooltipBox />} />
            <ReferenceLine y={0} stroke="#444" />
            <Legend {...LEG} />

            {/* μ=0.01 */}
            <Line type="monotone" dataKey="rms_01"  name="RMS μ=0.01"
              stroke={C01} strokeWidth={2} dot={false}
              isAnimationActive={false} connectNulls={false} />
            <Line type="monotone" dataKey="vmax_01" name="Vmax μ=0.01"
              stroke={C01} strokeWidth={1.5} strokeDasharray="6 3"
              dot={false} isAnimationActive={false} connectNulls={false} />

            {/* μ=0.05 */}
            <Line type="monotone" dataKey="rms_05"  name="RMS μ=0.05"
              stroke={C05} strokeWidth={2} dot={false}
              isAnimationActive={false} connectNulls={false} />
            <Line type="monotone" dataKey="vmax_05" name="Vmax μ=0.05"
              stroke={C05} strokeWidth={1.5} strokeDasharray="6 3"
              dot={false} isAnimationActive={false} connectNulls={false} />
          </LineChart>
        </ResponsiveContainer>
      </Panel>

      {/* ── ② 液面高さ・盛り上がり量 ────────────────────────────────── */}
      <Panel
        title="② 液面高さ & 盛り上がり量"
        sub="実線 = 壁際液面高さ　破線 = 中心液面高さ　点線 = 盛り上がり量 (= 中心 − 壁際)　単位 (mm)">
        <ResponsiveContainer width="100%" height={340}>
          <LineChart data={DATA} margin={{ top:4, right:24, bottom:14, left:16 }}>
            <CartesianGrid {...GRID} />
            <XAxis {...XAXIS} />
            <YAxis
              tick={{ fill:"#888", fontSize:10 }}
              label={{ value:"高さ (mm)", angle:-90, position:"insideLeft",
                        fill:"#888", fontSize:11 }} />
            <Tooltip content={<TooltipBox />} />
            <ReferenceLine y={0} stroke="#444" strokeDasharray="2 2" />
            <Legend {...LEG} />

            {/* μ=0.01 */}
            <Line type="monotone" dataKey="wall_h_01"   name="壁際 μ=0.01"
              stroke={C01} strokeWidth={2} dot={false}
              isAnimationActive={false} connectNulls={false} />
            <Line type="monotone" dataKey="center_h_01" name="中心 μ=0.01"
              stroke={C01} strokeWidth={1.5} strokeDasharray="6 3"
              dot={false} isAnimationActive={false} connectNulls={false} />
            <Line type="monotone" dataKey="rise_01"     name="盛り上がり μ=0.01"
              stroke={C01} strokeWidth={1.2} strokeDasharray="2 2"
              dot={false} isAnimationActive={false} connectNulls={false} />

            {/* μ=0.05 */}
            <Line type="monotone" dataKey="wall_h_05"   name="壁際 μ=0.05"
              stroke={C05} strokeWidth={2} dot={false}
              isAnimationActive={false} connectNulls={false} />
            <Line type="monotone" dataKey="center_h_05" name="中心 μ=0.05"
              stroke={C05} strokeWidth={1.5} strokeDasharray="6 3"
              dot={false} isAnimationActive={false} connectNulls={false} />
            <Line type="monotone" dataKey="rise_05"     name="盛り上がり μ=0.05"
              stroke={C05} strokeWidth={1.2} strokeDasharray="2 2"
              dot={false} isAnimationActive={false} connectNulls={false} />
          </LineChart>
        </ResponsiveContainer>
      </Panel>

      {/* Stats */}
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12 }}>
        {[
          { mu:"μ = 0.01", color:C01, rows:[
            ["静止判定 開始","frame 120  (t ≈ 0.072 s)"],
            ["終了","frame 1200  (t = 0.720 s)"],
            ["RMS速度 範囲","0.104 → 0.329 m/s"],
            ["最大速度 範囲","0.62 → 1.93 m/s"],
            ["壁際液面高さ","49.2 → 53.0 mm"],
            ["中心液面高さ","52.8 → 123.7 mm"],
            ["盛り上がり量","−73.9 → −1.4 mm"],
          ]},
          { mu:"μ = 0.05", color:C05, rows:[
            ["静止判定 開始","frame 120  (t ≈ 0.077 s)"],
            ["終了","frame 1179  (t = 1.130 s)"],
            ["RMS速度 範囲","0.018 → 0.260 m/s"],
            ["最大速度 範囲","0.15 → 1.89 m/s"],
            ["壁際液面高さ","46.3 → 48.1 mm"],
            ["中心液面高さ","49.7 → 124.7 mm"],
            ["盛り上がり量","−78.5 → −2.1 mm"],
          ]},
        ].map(col => (
          <div key={col.mu} style={{
            background:"#1a1a2e", border:`1px solid ${col.color}44`,
            borderRadius:10, padding:"12px 16px"
          }}>
            <div style={{ color:col.color, fontWeight:700,
                            fontSize:14, marginBottom:8 }}>{col.mu}</div>
            {col.rows.map(([k, v]) => (
              <div key={k} style={{ display:"flex", justifyContent:"space-between",
                                       fontSize:11, marginBottom:3, color:"#aaa" }}>
                <span>{k}</span>
                <span style={{ color:"#eee", fontFamily:"monospace" }}>{v}</span>
              </div>
            ))}
          </div>
        ))}
      </div>

      <p style={{ textAlign:"center", fontSize:11, color:"#555", marginTop:14 }}>
        ※ X軸は累積シミュレーション時間 (s) ／ 300点リサンプル ／
        μ=0.01 は 0.720 s 以降は非表示
      </p>
    </div>
  );
}
